import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.DdtnLau3.js";const b=JSON.parse('{"title":"Specification","description":"","frontmatter":{},"headers":[],"relativePath":"spec/index.md","filePath":"spec/index.md"}'),i={name:"spec/index.md"};function n(s,e,d,p,l,c){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="specification" tabindex="-1">Specification <a class="header-anchor" href="#specification" aria-label="Permalink to &quot;Specification&quot;">​</a></h1><p>These pages summarize the current Piwork implementation for developers. They adapt the source project&#39;s existing specifications; they do not define a competing API or package format.</p><p>Current delivery is <a href="https://github.com/pphboy/piwork/releases/tag/v0.0.2" target="_blank" rel="noreferrer">Piwork 0.0.2 Preview</a>, including the Web base and direct model management. All five runtime images were published, anonymously pulled and executed; see the <a href="/piwork/piwork/install/0.0.2-fb4f577da3b4-512ec778b267/release-manifest.json">release manifest</a>. Clean build source: <code>fb4f577da3b4d0008b97a59103b84efefbf9b508</code>; input SHA256: <code>512ec778b2671454ce1e66ceb11893f4f3ff908286ec2ae4947fd24fda100f37</code>. The release tag additionally includes publication materials and does not rewrite image build identity. The Web base retains its independent <a href="/piwork/piwork/install/0.0.2-fb4f577da3b4-512ec778b267/web-base-release.json">published receipt</a>. The native Windows client remains an experimental executable with formal native acceptance pending; see preview-verification.md in the release. Historical download directories keep their provenance.</p><table tabindex="0"><thead><tr><th>Area</th><th>Read here</th><th>Authoritative source</th></tr></thead><tbody><tr><td>Portable Work</td><td><a href="/piwork/spec/work.html">Work Spec</a></td><td><a href="https://github.com/pphboy/piwork/blob/main/docs/work-package-format.md" target="_blank" rel="noreferrer">Package format</a> and <a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/portable-work/spec.md" target="_blank" rel="noreferrer">portable-work</a></td></tr><tr><td>Managed capabilities</td><td><a href="/piwork/spec/service.html">Service Spec</a></td><td><a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/work-services/spec.md" target="_blank" rel="noreferrer">work-services</a> and <a href="https://github.com/pphboy/piwork/blob/main/internal/servicemcp/tools.json" target="_blank" rel="noreferrer">MCP tools</a></td></tr><tr><td>Intelligent execution</td><td><a href="/piwork/spec/harness.html">Harness Spec</a></td><td><a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/agent-conversation/spec.md" target="_blank" rel="noreferrer">agent-conversation</a> and <a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/piwork-brain/spec.md" target="_blank" rel="noreferrer">piwork-brain</a></td></tr></tbody></table><h2 id="status-labels" tabindex="-1">Status labels <a class="header-anchor" href="#status-labels" aria-label="Permalink to &quot;Status labels&quot;">​</a></h2><ul><li><strong>Current behavior / format:</strong> implemented behavior and source contracts.</li><li><strong>Experimental:</strong> existing behavior whose contracts and user experience are still evolving.</li><li><strong>Future direction:</strong> a product goal that is not an implemented guarantee.</li></ul><p>For mismatches, prefer current implementation over older design notes. <a href="https://github.com/pphboy/piwork/issues" target="_blank" rel="noreferrer">Open an issue</a> with the command, image version, and observed result.</p><h2 id="current-delivery-boundary" tabindex="-1">Current delivery boundary <a class="header-anchor" href="#current-delivery-boundary" aria-label="Permalink to &quot;Current delivery boundary&quot;">​</a></h2><p>Core manages one local Linux Docker Engine through its Unix API. Docker delivery targets <code>linux/amd64</code> and Engine 28+; Compose 2.24+ is only needed for the Core Demo or advanced Compose setups. The Go CLI has Windows and Linux targets; outstanding native Windows checks are documented in the source <a href="https://github.com/pphboy/piwork/blob/main/docs/cli-platforms.md" target="_blank" rel="noreferrer">CLI platform guide</a>.</p><p>A Work requires ready runtime images and model configuration. Core shutdown stops managed runtime containers while retaining durable state. Closing Desktop or the CLI does not stop the Work.</p><p><a href="/piwork/guide/quick-start.html">Terminal Quick Start</a> uses independent Core/CLI images; Core also supports Core-only Compose, with combined usage in the single-host example; native builds and administrator operations have separate navigation.</p>',11)])])}const m=t(i,[["render",n]]);export{b as __pageData,m as default};
